from pathlib import Path


APP = Path('/app/app')
MAIN = APP / 'main.py'
TEMPLATES = APP / 'templates'
STATIC = APP / 'static'


def write_template(name: str, content: str) -> None:
    (TEMPLATES / name).write_text(content, encoding='utf-8')


write_template('google_wallet.html', r'''{% extends "base.html" %}
{% block title %}Google Wallet para programas de lealtad | Exponenta{% endblock %}
{% block body %}
<main class="wallet-site">
  <header class="wallet-nav">
    <div class="wallet-wrap"><a href="/" class="wallet-brand"><img src="/static/exponenta-logo.svg" alt="Exponenta"></a><nav><a href="#como-funciona">Cómo funciona</a><a href="#seguridad">Seguridad</a><a href="#preguntas">Preguntas</a></nav><a class="wallet-nav-cta" href="/login">Abrir plataforma</a></div>
  </header>
  <section class="wallet-hero"><div class="wallet-wrap wallet-hero-grid">
    <div><span class="wallet-kicker">GOOGLE WALLET · PROGRAMAS DE LEALTAD</span><h1>Una lealtad que vive en el <em>celular.</em></h1><p>Exponenta ayuda a negocios locales a operar programas de visitas, puntos y recompensas mediante pases individuales de Google Wallet.</p><div class="wallet-actions"><a class="wallet-primary" href="#como-funciona">Conocer el funcionamiento <b>↓</b></a><a class="wallet-secondary" href="/">Conocer Exponenta</a></div></div>
    <div class="wallet-pass-frame" aria-label="Ejemplo de pase de lealtad"><div class="wallet-pass"><div class="wallet-pass-top"><span class="wallet-pass-mark">E</span><strong>CAFÉ EXPO</strong><small>LEALTAD</small></div><div class="wallet-pass-body"><small>MIEMBRO</small><h2>Mariana López</h2><div class="wallet-pass-stat"><span>VISITAS</span><b>6 <i>de 9</i></b></div><div class="wallet-dots"><i></i><i></i><i></i><i></i><i></i><i></i><i class="empty"></i><i class="empty"></i><i class="empty"></i></div><div class="wallet-reward"><small>SIGUIENTE RECOMPENSA</small><b>Un café de cortesía</b></div></div></div><div class="wallet-update"><span>✓</span><div><b>Tarjeta actualizada</b><small>Visita registrada correctamente</small></div></div></div>
  </div></section>
  <section class="wallet-purpose"><div class="wallet-wrap"><span class="wallet-kicker">NUESTRO CASO DE USO</span><h2>Exponenta es una plataforma B2B para programas de lealtad de negocios locales.</h2><p class="wallet-lead">Restaurantes, cafeterías, salones, gimnasios, comercios y servicios configuran su propio programa. Cada cliente final recibe un pase único, asociado exclusivamente a su relación con ese negocio.</p><div class="wallet-grid-three"><article><span>01</span><h3>El negocio configura</h3><p>Su marca, mecánica de visitas o puntos, recompensas y reglas del programa.</p></article><article><span>02</span><h3>El cliente se une</h3><p>Recibe un pase de lealtad individual y lo guarda voluntariamente en Google Wallet.</p></article><article><span>03</span><h3>El pase se actualiza</h3><p>Después de una visita validada, un sello, puntos acreditados o una recompensa canjeada.</p></article></div></div></section>
  <section class="wallet-flow" id="como-funciona"><div class="wallet-wrap"><div class="wallet-flow-heading"><span class="wallet-kicker light">OPERACIÓN DEL PROGRAMA</span><h2>Una tarjeta única para cada cliente. Una operación clara para cada negocio.</h2></div><div class="wallet-flow-grid"><article><b>1</b><h3>Alta del miembro</h3><p>El cliente se registra una vez y recibe una membresía individual.</p></article><article><b>2</b><h3>Emisión del pase</h3><p>La plataforma genera su objeto de lealtad y el cliente puede guardarlo en Google Wallet.</p></article><article><b>3</b><h3>Visita verificada</h3><p>El negocio valida la interacción desde Exponenta mediante QR atendido o una experiencia NFC controlada.</p></article><article><b>4</b><h3>Actualización</h3><p>Exponenta actualiza saldo, visitas, nivel o recompensa conforme a la acción validada.</p></article></div></div></section>
  <section class="wallet-fields"><div class="wallet-wrap wallet-fields-grid"><div><span class="wallet-kicker">INFORMACIÓN DEL PASE</span><h2>Datos útiles para el programa. Nada de datos de pago.</h2><p>Los pases se usan exclusivamente para identificar la membresía y mostrar el avance de lealtad de cada cliente.</p></div><div class="wallet-field-card"><p><b>Puede mostrar</b></p><ul><li>Nombre del negocio y su identidad visual</li><li>Identificador de membresía</li><li>Visitas, sellos o balance de puntos</li><li>Nivel y siguiente recompensa</li><li>Fechas relevantes y términos del programa</li></ul><p><b>No incluimos</b></p><ul class="no"><li>Datos de tarjeta bancaria o pagos</li><li>Credenciales de acceso</li><li>Datos sensibles</li><li>Datos personales dentro del QR</li></ul></div></div></section>
  <section class="wallet-security" id="seguridad"><div class="wallet-wrap wallet-security-grid"><div><span class="wallet-kicker light">SEGURIDAD Y CONTROL</span><h2>El pase no equivale a dinero ni reemplaza un método de pago.</h2><p>La operación de lealtad se valida dentro de la plataforma. Los identificadores operativos usan tokens opacos y revocables; no se imprime información personal dentro de un código QR.</p></div><div class="wallet-security-list"><p><b>Validación atendida</b><span>Las visitas y canjes requieren una acción validada por el negocio.</span></p><p><b>Identificadores opacos</b><span>Los QR contienen tokens técnicos, no nombres, correos ni teléfonos.</span></p><p><b>Actualizaciones auditables</b><span>Las acciones de sellado, puntos y canje forman parte del historial del programa.</span></p><p><b>Acceso por rol</b><span>Los negocios gestionan solamente sus propios programas y miembros.</span></p></div></div></section>
  <section class="wallet-faq wallet-wrap" id="preguntas"><span class="wallet-kicker">PREGUNTAS FRECUENTES</span><h2>Lo esencial del servicio.</h2><details open><summary>¿Exponenta procesa pagos con Google Wallet?</summary><p>No. Exponenta utiliza Google Wallet para pases de lealtad; no procesa pagos ni almacena datos de tarjetas bancarias.</p></details><details><summary>¿Un cliente puede tener más de un pase?</summary><p>Sí. Cada pase corresponde a un programa de un negocio participante y a una membresía individual dentro de ese programa.</p></details><details><summary>¿Qué actualiza el pase?</summary><p>Visitas, sellos, puntos, nivel, recompensa disponible o mensajes relacionados con el programa, cuando una acción es validada.</p></details><details><summary>¿El QR contiene datos personales?</summary><p>No. El QR utiliza un identificador opaco y revocable para validar la operación sin exponer información personal.</p></details></section>
  <section class="wallet-contact"><div class="wallet-wrap"><span class="wallet-kicker light">EXPONENTA</span><h2>Construimos conexiones que hacen crecer negocios.</h2><p>Para información sobre la plataforma, los programas de lealtad o el uso de Google Wallet:</p><a href="mailto:hola@exponenta.mx">hola@exponenta.mx</a><div class="wallet-legal"><a href="/privacy">Aviso de privacidad</a><a href="/terms">Términos de uso</a><a href="/">Sitio principal</a></div></div></section>
</main>
{% endblock %}''')

write_template('privacy.html', r'''{% extends "base.html" %}{% block title %}Aviso de privacidad | Exponenta{% endblock %}{% block body %}<main class="legal-page"><div class="legal-wrap"><a href="/wallet">← Volver a Google Wallet</a><span>EXPONENTA</span><h1>Aviso de privacidad</h1><p class="legal-date">Última actualización: 28 de septiembre de 2026</p><h2>Información que tratamos</h2><p>Exponenta puede tratar los datos de contacto y membresía proporcionados para operar programas de lealtad de negocios participantes, incluyendo nombre, teléfono o correo cuando el cliente los proporciona, e información de actividad como visitas, puntos y recompensas.</p><h2>Finalidad</h2><p>Usamos la información para crear y recuperar la membresía, operar el programa de lealtad, prevenir duplicados y fraude, actualizar pases digitales y atender solicitudes relacionadas con el servicio.</p><h2>Google Wallet</h2><p>Los pases de Google Wallet muestran información de lealtad. No utilizamos el servicio para pagos ni incluimos datos de tarjeta bancaria. Los códigos QR contienen identificadores técnicos opacos, no datos personales legibles.</p><h2>Contacto</h2><p>Para asuntos de privacidad, escribe a <a href="mailto:hola@exponenta.mx">hola@exponenta.mx</a>.</p></div></main>{% endblock %}''')

write_template('terms.html', r'''{% extends "base.html" %}{% block title %}Términos de uso | Exponenta{% endblock %}{% block body %}<main class="legal-page"><div class="legal-wrap"><a href="/wallet">← Volver a Google Wallet</a><span>EXPONENTA</span><h1>Términos de uso</h1><p class="legal-date">Última actualización: 28 de septiembre de 2026</p><h2>Servicio</h2><p>Exponenta proporciona tecnología para que negocios participantes operen programas de lealtad digitales. Cada negocio define sus recompensas, reglas, vigencia y condiciones aplicables a su propio programa.</p><h2>Pases digitales</h2><p>Un pase digital identifica una membresía y muestra información de lealtad. No es un medio de pago, valor almacenado ni garantía de una recompensa fuera de las reglas del negocio participante.</p><h2>Uso responsable</h2><p>Los beneficios se acreditan y canjean conforme a acciones verificadas dentro del programa. Exponenta y los negocios participantes pueden investigar o cancelar operaciones que indiquen uso indebido, fraude o incumplimiento de las reglas del programa.</p><h2>Contacto</h2><p>Escribe a <a href="mailto:hola@exponenta.mx">hola@exponenta.mx</a> para consultas relacionadas con el servicio.</p></div></main>{% endblock %}''')

main = MAIN.read_text(encoding='utf-8')
needle = '''@app.get("/login", response_class=HTMLResponse)\ndef login_page'''
routes = '''@app.get("/wallet", response_class=HTMLResponse)\ndef google_wallet_public_page(request: Request):\n    return render(request, "google_wallet.html")\n\n\n@app.get("/privacy", response_class=HTMLResponse)\ndef privacy_page(request: Request):\n    return render(request, "privacy.html")\n\n\n@app.get("/terms", response_class=HTMLResponse)\ndef terms_page(request: Request):\n    return render(request, "terms.html")\n\n\n'''
if 'def google_wallet_public_page' not in main:
    if needle not in main:
        raise SystemExit('Route insertion point not found')
    MAIN.write_text(main.replace(needle, routes + needle), encoding='utf-8')

